@startuml

class Provider {
  + Name : string
  + Location : string
}

class Cruise {
  + Number : int
  + Name : string
  + StartDate : date
  + EndDate : date
}

class Employee {
  + Name : string
  + SocialSecurityNumber : string
}

class Guest {
  + Name : string
  + IsVIP : boolean
}

class Ship {
  + Name : string
  + Decks : int
  + Length : float
  + PassengerCount : int
}

class TravelAgency {
  + Name : string
  + Address : string
}

class Booking {
  + BookingNumber : string
  + BookingDate : date
}

class DestinationArea {
  + Name : string
  + SeaName : string
}

class Show {
  + Title : string
  + Duration : int
}

class Ticket {
}

Provider "1" -- "*" Cruise
Cruise "*" -- "*" Employee
Cruise "0..*" -- "1" Ship
Cruise "1" -- "1" DestinationArea
Cruise "1" -- "*" Show
Cruise "1" -- "*" Ticket
Cruise "*" -- "*" Guest
TravelAgency "1" -- "*" Booking
Booking "1" -- "1" Cruise
Guest "1" -- "0..*" Ticket
Ticket "0..*" -- "1" Cruise

@enduml

